def validate_input(s):
    if not s or not s.strip():
        raise ValueError('input cannot be empty')
    return s.strip()

def normalize(s):
    s = s.lower().strip()
    return s.replace(' ', '_')

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

